INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Kenadsa Colliery (Bechar Basin)', 'Closed — no operator since 1975. Formerly: Compagnie des Houilleres de Kenadsa (French colonial); post-independence SONAREM', NULL, NULL, NULL, 'Algeria', 'Bechar Province', 'Kenadsa town, ~31°35''N 2°17''W; Hammada stony desert, northwest Sahara margin', 31.576, -2.284, 'Oran (~700 km northwest via rail/road)', 'Bechar railway station (24 km east) — connected to national network via Abadla', 1917, 58, 'Compagnie des Houilleres de Kenadsa (French colonial)', '[{"year": 1917, "event": "Mining commenced under French colonial Compagnie des Houilleres de Kenadsa"}, {"year": 1940, "event": "Peak production period — World War II wartime demand"}, {"year": 1962, "event": "Algeria independence; mine nationalised; operated by state under SONAREM"}, {"year": 1975, "event": "Mine permanently closed — economic decision (high transport costs vs eastern Algeria oil/gas; depleted accessible reserves)"}]'::jsonb, '[{"year": null, "event": "First industrial mine in southern Algeria"}, {"year": null, "event": "Peak output 1940s–1950s (~300,000 tpa wartime peak)"}, {"year": null, "event": "Site designated cultural and historical heritage in Bechar Province (2019)"}]'::jsonb, '[{"year": null, "event": "Legacy spoil tips used as illegal waste dumps by local residents post-closure"}, {"year": null, "event": "Brownfield contamination: soil and air pollution risk from unprotected spoil heaps"}, {"year": null, "event": "Teenagers accessing unsafe derelict wash-house structure — safety hazard documented 2019"}]'::jsonb, NULL, 'Bituminous', 'Carboniferous (Westphalian C-D) bituminous coal; moderate rank; two sub-basins Kenadsa and Ksiksou', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Underground horizontal adits and inclined shafts; conventional drill-and-blast', NULL, NULL, NULL, NULL, NULL, 'Oran', '["Narrow-gauge mine railway to Kenadsa wash plant", "Road/rail to Bechar"]'::jsonb, NULL, false, '[]'::jsonb)
