VALUES ('Morupule Coal Mine (MCM)', 'Morupule Coal Mine (Pty) Ltd', 'Mining lease — 42,531.625 ha', NULL, NULL, 'Botswana', 'Central District', '14 km northwest of Palapye, Serowe–Palapye Road, Central District, Botswana', -22.533, 27.117, 'Durban, South Africa (~1,400 km southeast via rail)', 'Botswana Rail network — Palapye station (~14 km southeast)', 1971, 53, 'Anglo American Corporation', '[{"year": 1973, "event": "First coal production — Anglo American subsidiary; supplied BCL copper/nickel smelter at Selebi-Phikwe"}, {"year": 1986, "event": "Morupule A Power Station (132 MW, BPC) commissioned — MCM became primary fuel supplier"}, {"year": 2000, "event": "Debswana (De Beers / Government of Botswana JV) acquired 100% of MCM"}, {"year": 2012, "event": "Phase I expansion completed; Morupule B Power Station (600 MW) commissioned; MCM capacity increased to 2.8 Mtpa"}, {"year": 2016, "event": "MCM transferred from Debswana to MDCB — full 100% government ownership"}, {"year": 2023, "event": "50th anniversary celebrated; 22 years without fatality milestone"}]'::jsonb, '[{"year": null, "event": "Only continuously operating coal mine in Botswana for 50 years"}, {"year": null, "event": "ISO 14001, ISO 9001, ISO 45001 certified"}, {"year": null, "event": "Botswana strategic energy backbone — supplies Morupule A (132 MW) and B (600 MW) power stations"}, {"year": null, "event": "4,284.9 Mt total classified coal resource; ~5 billion tonnes overall coalfield"}]'::jsonb, '[{"year": null, "event": "Morupule B Power Station (600 MW) has faced persistent technical problems since 2012 — operating well below capacity; BPC remedial works targeting 2027"}]'::jsonb, NULL, 'Sub-bituminous to semi-bituminous thermal', 'Karoo Supergroup Palapye Group; No. 1 Seam avg 8.5 m thick; CV ~23.5 MJ/kg air-dry', 5650, NULL, NULL, NULL, NULL, 4200000, NULL, 'Underground bord-and-pillar with continuous miners; Motheo Opencast under development', NULL, NULL, NULL, NULL, NULL, 'Durban', '["Conveyor (mine-mouth to power stations)", "Botswana Rail to export markets"]'::jsonb, NULL, true, '["ISO 14001", "ISO 9001", "ISO 45001"]'::jsonb)
