VALUES ('Masama Coal Mine — Mmamabula West Coalfield (Minergy Coal)', 'Minergy Coal (Pty) Ltd — mining contractor: Meropa Resources (from May 2024)', 'Prospecting Licence for Coal and Coal-Bed Methane — Mmamabula West edge', NULL, NULL, 'Botswana', 'Central District', 'Mmamabula West coalfield, ~200 km south of Francistown, Central District, Botswana', -24.10, 26.10, 'Richards Bay, South Africa (~900 km southeast via proposed Lephalale Rail Link)', 'Botswana main railway line (~65 km east by road); Lephalale Rail Link (proposed 24 Mtpa export line)', 2018, 7, 'Minergy Limited', '[{"year": 2018, "event": "Masama Mine (Minergy) commenced production — nameplate 1.5 Mtpa"}, {"year": 2023, "event": "Masama Mine shutdown — contractor Jarcon ceased operations (March 2023); mine idle"}, {"year": 2024, "event": "Masama Mine resumed production under new contractor Meropa Resources (May 2024)"}]'::jsonb, '[{"year": null, "event": "Only currently operating coal mine besides Morupule in Botswana"}, {"year": null, "event": "374–380 Mt JORC-compliant coal resource; A-Seam 4–6 m thick"}, {"year": 2023, "event": "Jindal groundbreaking October 2023 for 600 MW JMEP power plant"}, {"year": null, "event": "Jindal coal mine development commenced (~4.5 Mtpa planned)"}]'::jsonb, '[{"year": 2023, "event": "March 2023 unplanned shutdown — Jarcon contractor unilaterally ceased mining; loss of customers and revenue"}, {"year": null, "event": "African Energy Resources hived off Botswana coal assets 2021 — reflecting global coal finance retreat"}]'::jsonb, NULL, 'Sub-bituminous to bituminous thermal', 'Mmamabula coalfield; A-Seam low ash, low sulphur, high reactive vitrinite; depth 100–150 m', NULL, NULL, NULL, NULL, NULL, 1500000, NULL, 'Open cast; road haulage to rail loading', NULL, NULL, NULL, NULL, NULL, 'Richards Bay', '["Road haulage to rail loading (~65 km to main Botswana railway)"]'::jsonb, NULL, true, '[]'::jsonb)
