VALUES ('Chad — Lake Chad Basin Lignite Occurrences (Undeveloped)', 'None', NULL, NULL, NULL, 'Chad', 'Lake Chad Basin — Kanem, Lac, Bahr el Ghazal regions', 'Lake Chad Basin, northwestern and central Chad', 13.50, 14.50, 'Douala, Cameroon (~1,500 km southwest via Chad–Cameroon road)', 'None — Chad has no operating railway', NULL, NULL, NULL, '[]'::jsonb, '[{"year": 2003, "event": "Chad oil production commenced: Doba Basin via Chad–Cameroon Pipeline (~130,000 b/d)"}, {"year": null, "event": "Lake Chad shrinkage: basin has reduced ~90% since 1960s due to climate change and water extraction"}, {"year": null, "event": "Chad is among world''s poorest countries; GDP ~US$11 billion (2023)"}]'::jsonb, '[{"year": null, "event": "Lake Chad environmental crisis — one of world''s fastest-shrinking lakes"}, {"year": null, "event": "Boko Haram and ISWAP activity in Lake Chad region creates security risks"}]'::jsonb, NULL, 'Lignite', 'Very low rank; lignite, high ash, high moisture; Cretaceous continental sequences; not commercially viable', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '[]'::jsonb)
