INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Lukuga Coalfield — Tanganyika Province (Former Katanga)', 'No current industrial operator. Historical: Gecamines. Current: informal artisanal mining only', 'Cadastre Minier (CAMI) — concession details not publicly confirmed', NULL, NULL, 'Democratic Republic of Congo', 'Tanganyika Province', 'Lukuga River valley, ~45 km west of Kalemie, eastern DRC', -5.93, 29.20, 'Kalemie (Lake Tanganyika port, ~45 km east); Dar es Salaam (~800 km via lake and TAZARA)', 'Ligne du Bas-Congo au Katanga (BCK) — severely damaged/non-operational; access via Lake Tanganyika ferry to Kigoma (Tanzania)', NULL, NULL, 'Union Miniere du Haut-Katanga (UMHK)', '[{"year": 1910, "event": "Coal identified by UMHK/Belgian colonial surveys"}, {"year": 1950, "event": "Small underground trial mines operated by UMHK to supply local industrial demand"}, {"year": 1966, "event": "Gecamines formed (successor to UMHK); took over coal interests"}, {"year": 1990, "event": "Gecamines collapse + DRC civil war disrupts all operations; Lukuga effectively abandoned"}, {"year": 2019, "event": "Luena Katanga power station re-proposed (coal + 30 MW) — Gecamines announcement; stalled as of 2023-2024"}]'::jsonb, '[{"year": null, "event": "One of the few significant coal deposits in Central Africa"}, {"year": null, "event": "~300–500 Mt estimated resources (historical Belgian colonial-era UMHK surveys)"}, {"year": null, "event": "Sub-bituminous to bituminous; CV ~20–25 MJ/kg; Permian Karoo-equivalent"}]'::jsonb, '[{"year": null, "event": "Ongoing insecurity in eastern DRC (M23, FDLR, various armed groups) severely limits any development"}, {"year": null, "event": "Kalemie-Albertville railway line to Copperbelt has been non-operational for decades"}]'::jsonb, NULL, 'Sub-bituminous to bituminous', 'Permian Karoo-age Lukuga Formation; Lukuga Formation coal-bearing sediments; East African Rift margin', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Historical: small underground adits. Current: artisanal pick/shovel', NULL, NULL, NULL, NULL, NULL, 'Kalemie', '["Lake Tanganyika ferry"]'::jsonb, NULL, false, '[]'::jsonb)
