VALUES ('Walikale Region — No Coal Mine (Tin/Coltan Territory)', 'No coal operator. Primary industrial operator: Alphamin Bisie Mining (ABM) for tin', 'N/A for coal', NULL, NULL, 'Democratic Republic of Congo', 'North Kivu Province', 'Walikale Territory, North Kivu, eastern DRC (~220 km west of Goma)', -1.43, 28.04, 'Goma (North Kivu) ~220 km east — lake access; no deep-water port', 'None — no railway in North Kivu', NULL, NULL, NULL, '[]'::jsonb, '[{"year": null, "event": "CONFIRMED: No coal has been discovered in Walikale. Territory mineral identity is exclusively cassiterite, coltan, wolframite, gold, gemstones"}, {"year": null, "event": "Alphamin Bisie Mining (ABM): ~4% of global tin supply from Bisie deposit"}, {"year": null, "event": "Walikale geology: Precambrian metamorphic terrain (Kibaran Orogeny) — fundamentally incompatible with coal formation"}]'::jsonb, '[{"year": 2010, "event": "Walikale Massacre — mass rape by armed groups near mining sites"}, {"year": null, "event": "Endemic conflict between armed groups, FARDC, and artisanal miners over cassiterite/coltan revenues"}]'::jsonb, NULL, 'N/A — no coal', 'Precambrian metamorphic rocks (schists, quartzites, granites); no coal deposit; geology incompatible with coal formation', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '[]'::jsonb)
