INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Sakoa Coalfield — Madagascar Consolidated Mining / Red Island Minerals', 'Madagascar Consolidated Mining (Pty) Ltd — subsidiary of Red Island Minerals', 'Multiple prospecting and exploration licences over Sakoa field', NULL, NULL, 'Madagascar', 'Atsimo-Andrefana Province', 'Sakoa region, Atsimo-Andrefana Province, southwestern Madagascar (~200 km northeast of Toliara)', -22.10, 44.10, 'Toliara (Tulear) — ~200 km southwest', 'None in southwestern Madagascar — road access only (RN7 to Toliara via Andranovory)', NULL, NULL, 'Red Island Minerals', '[{"year": 1908, "event": "First coal discovery in Sakoa Basin made during French colonial geological surveys"}, {"year": 2008, "event": "Pan African Mining Corporation (PAMC) commenced intensive exploration in Sakoa Basin"}, {"year": 2008, "event": "Madagascar Consolidated Mining (Red Island Minerals subsidiary) acquired majority of commercially valuable Sakoa field licences"}]'::jsonb, '[{"year": null, "event": "Sakoa field is highest-quality coal in the basin"}, {"year": null, "event": "Madagascar government promoting mining investment including coal for energy development"}, {"year": null, "event": "Madagascar electricity: primarily diesel generation and small hydro; <30% electrification nationally"}]'::jsonb, '[{"year": 2009, "event": "2009 Madagascar political crisis (coup) disrupted mining investment environment"}, {"year": null, "event": "Madagascar ranked among world''s most fragile states; governance challenges affect investment"}]'::jsonb, NULL, 'Sub-bituminous to bituminous', 'Permian Karoo Supergroup (Sakoa Group) coal measures; Morondava Basin', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Proposed — not determined', NULL, NULL, NULL, NULL, NULL, 'Toliara (proposed)', '["Proposed: road to Toliara port"]'::jsonb, NULL, false, '[]'::jsonb)
