INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Imaloto Coal Mine / Imaloto Integrated Coal Power Project', 'Lemur Holdings Limited (Bushveld Minerals Ltd subsidiary); Coal Mining Madagascar S.A.R.L (CMM)', 'Mining Permit No. 4578 (issued 29 Nov 2005); Prospecting Permits 3196, 12653, 26904, 27163 — total 81.25 km2', NULL, NULL, 'Madagascar', 'Atsimo-Andrefana Province', 'Imaloto River valley, 15 km NE of Benenitra town; 158 km east of Toliara city', -22.60, 44.80, 'Toliara (Tulear) — 158 km west; access via RN7 (70 km paved) then ~150 km rural dirt road', 'None — southwestern Madagascar has no railway', 2011, NULL, 'Lemur Resources (acquired Coal of Madagascar Limited April 2011)', '[{"year": 2005, "event": "Mining Permit No. 4578 issued to Coal Mining Madagascar S.A.R.L"}, {"year": 2011, "event": "Lemur Resources acquired Coal of Madagascar Limited — consolidated Imaloto licences"}, {"year": 2012, "event": "Decision to expand project scope from coal mine only to integrated 45 MW coal power plant + 200 km transmission line"}, {"year": 2017, "event": "PPA signed with JIRAMA (national utility) — 10 MW take; remainder to large industrial consumers"}, {"year": 2018, "event": "30-year concession agreement signed with Madagascar government; Lemur became wholly owned subsidiary of Bushveld Minerals"}, {"year": 2020, "event": "DBSA appointed as Mandated Lead Arranger for up to US$155M construction financing"}, {"year": 2021, "event": "China COP26 coal finance halt created financing uncertainty for Sinohydro role"}, {"year": 2023, "event": "Lemur in final phase of Definitive Feasibility Study; SAMREC CPR updated October 2023"}]'::jsonb, '[{"year": null, "event": "Only coal exploitation licence in Madagascar"}, {"year": null, "event": "136 Mt JORC-compliant coal resource (90% Measured + Indicated)"}, {"year": null, "event": "30-year concession agreement signed with Madagascar government (2018)"}, {"year": null, "event": "South Madagascar has <20 MW total power — Imaloto 60 MW would be transformative"}, {"year": null, "event": "Sub-Bituminous Low Rank A to Medium Rank D (Vitrinite Ro 0.3–0.6%)"}]'::jsonb, '[{"year": 2021, "event": "China COP26 coal finance halt — direct impact on Sinohydro partnership viability"}, {"year": null, "event": "Lemur parent Bushveld Minerals has faced financial challenges including liquidity issues in vanadium operations (2022–2024)"}]'::jsonb, NULL, 'Sub-bituminous thermal', 'Permian Karoo Supergroup (Sakoa Group); Main Seam (highest quality), Upper Seam, Top Seam; Imaloto Basin sub-basin of Morondava Basin', NULL, NULL, NULL, NULL, NULL, 0, NULL, 'Open pit initially; underground for deeper seams (proposed)', NULL, NULL, NULL, NULL, NULL, 'Toliara (proposed)', '["Mine-mouth conveyor to 60 MW power plant on site; 200+ km new transmission line to southern grid"]'::jsonb, NULL, false, '[]'::jsonb)
