INSERT INTO public.coal_mines (mine_name, operator, license_number, contact_email, contact_phone, country, region, address, latitude, longitude, nearest_port, nearest_railway, founded_year, years_in_operation, original_owner, ownership_changes, major_milestones, notable_incidents, estimated_mine_life_remaining_years, coal_type, grade, calorific_value_kcal_kg, moisture_percent, ash_percent, sulfur_percent, size_mm, annual_capacity_tonnes, available_stock_tonnes, mining_method, price_per_tonne_usd, price_basis, minimum_order_tonnes, payment_terms, contract_types, loading_port, transport_modes, lead_time_days, export_license, certifications)
VALUES ('Maloma Colliery (Maloma Anthracite Mine)', 'Maloma Colliery Limited (MCL)', 'Mining licence — Shiselweni and Lubombo regions; Mining Permit (first prospecting licence 1989; production commenced 1992)', NULL, NULL, 'Eswatini', 'Shiselweni Region and Lubombo Region', '25 km west of Nsoko, Shiselweni Region, southern Kingdom of Eswatini', -27.05, 31.65, 'Richards Bay, South Africa (~300 km east via road/rail through Eswatini and KZN)', 'Eswatini Railway (SWAZIRAIL) — connects to SA network; Maloma has rail connection', 1992, 33, 'Carbonex (1991–1996)', '[{"year": 1989, "event": "Prospecting licence received; exploration commenced"}, {"year": 1991, "event": "MCL incorporated; Tibiyo TakaNgwane and Government partnered with Carbonex (50% commercial share)"}, {"year": 1992, "event": "Production commenced"}, {"year": 2001, "event": "Xstrata Alloys (South Africa) acquired 50% commercial stake from Koch; annual capacity ~310,000 tpa anthracite"}, {"year": 2010, "event": "Chancellor House Holdings (SA) acquired from Xstrata"}, {"year": 2020, "event": "Mine-X / Minex Mining Services (Michello Shakantu) acquired 50% — first time 100% Eswatini-owned in 28 years"}, {"year": 2023, "event": "Record coal production year; production surged 30%"}]'::jsonb, '[{"year": null, "event": "Only operating coal mine in Eswatini and the only mine of any kind operating in the Kingdom"}, {"year": null, "event": "All anthracite production exported to South Africa for metallurgical/steel industry use"}, {"year": null, "event": "Customers: Samancor Chrome, Richards Bay Titanium, Bright Alloys; potential offtaker Glencore"}, {"year": null, "event": "1.2 million+ fatality-free production shifts"}, {"year": null, "event": "ISO 9001, ISO 45001, ISO 14001 certified"}, {"year": null, "event": "100% Eswatini-owned since 2020 — significant governance transformation"}]'::jsonb, '[{"year": null, "event": "Mpaka Colliery (adjacent met coal project) — proposals to open after suspension (2012); no updates since 2020; likely cancelled"}]'::jsonb, NULL, 'Anthracite', 'Karoo Monocline; Upper Beaufort Group; thermal metamorphism by dolerite dykes/sills to high-grade anthracite; 8-ash grade', NULL, NULL, NULL, NULL, NULL, 310000, NULL, 'Underground bord-and-pillar in complex geologically disturbed terrain (dolerite dykes/sills)', NULL, NULL, NULL, NULL, NULL, 'Richards Bay', '["Road haulage", "Eswatini Railway (SWAZIRAIL) to South Africa via Golela/KZN border"]'::jsonb, NULL, true, '["ISO 9001", "ISO 45001", "ISO 14001"]'::jsonb)
