VALUES ('Gafsa Basin — Lignite Occurrences (No Commercial Coal Mining)', 'No coal operator. Gafsa Basin dominated by phosphate mining: CPG and GCT', NULL, NULL, NULL, 'Tunisia', 'Gafsa Governorate', 'Gafsa Basin, ~350 km southwest of Tunis', 34.40, 8.80, 'Sfax (~150 km east) — main phosphate export port; or Gabes (~120 km east)', 'CPG phosphate railway network (Metlaoui to Sfax/Gabes); national SNCFT network', NULL, NULL, NULL, '[]'::jsonb, '[{"year": null, "event": "Gafsa Basin: major phosphate mining hub — CPG produces ~4 million tonnes phosphate rock/yr"}, {"year": null, "event": "2010–2011 Gafsa Phosphate Basin: major protests / January Revolution origin — worker unemployment and inequality led to Jasmine Revolution"}, {"year": null, "event": "Tunisia energy sector: oil/gas (ETAP), wind (Sfax area), solar (planned); no coal power stations"}, {"year": null, "event": "Tunisia is a net energy importer; relies on Algeria gas pipeline and electricity interconnections"}]'::jsonb, '[{"year": null, "event": "Ongoing social unrest in Gafsa mining basin — CPG worker protests, mine blockades, unemployment grievances (2011–ongoing)"}, {"year": null, "event": "CPG production disrupted repeatedly by social protests (2015: production fell from 8 Mt/yr pre-2011 to ~3.8 Mt/yr)"}]'::jsonb, NULL, 'Lignite', 'Very low rank; Eocene–Oligocene continental; minor lignite lenses in phosphate basin; commercially irrelevant', NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, '[]'::jsonb)
